import {FEATURES} from './community-features.js';
import {CLIMATE_LAYERS,layerDefinition,layerControls,climatePanel} from './climate-view.js';
import {createHailMap,hailAge} from './hail-map.js';
import {CITIES,normalizeCity} from './places.js';
import {esc,weatherName,miniWeather,valueText,numeric,currentHour,bestWindow,trendSummary,parseRadar,cityReports} from './weather-tools.js';
const $=s=>document.querySelector(s);
export function createAtlas(ctx){
 let hailRadar=false;const radarVisible=()=>layer==='radar'||layer==='grandine'&&hailRadar&&mode()==='map';
 let quality='high',radarPlaying=false,radarTimer=0,radarGeneration=0;try{if(localStorage.getItem('ms-globe-quality')==='light')quality='light'}catch{}
 let timeOffset=0,timeData=null,timeLoading=false,timeError='';let lastPlaceKey='';let layer='meteo',cities=CITIES,cityLoaded=0,cityLoading=false,cityError='',posts=[],postsLoaded=0,postLoading=false,reportsTruncated=false,radarData=null,radarAt=0,radarIndex=0,radarLoading=false,radarError='',scene=null,sceneType='',view=null,sequence=0,art=null,events=null,weatherTab='oggi',activity='walk',compare='milano';const imageCache=new Map();
 const isAtlas=()=>['mondo','mappa','radar','grandine-mappa'].includes(ctx.get().route),mode=()=>['mappa','radar','grandine-mappa'].includes(ctx.get().route)?'map':'globe';
 const hailMap=createHailMap({login:ctx.login,radarEnabled:()=>hailRadar,setRadar:value=>{hailRadar=value;stopRadar();if(value)loadRadar();else scene?.clearRadar?.();refreshRadarControls()},get:ctx.get,api:ctx.api,toast:ctx.toast,modal:ctx.modal,select,onUpdate:()=>refresh(),askAI:question=>ctx.askHail(question)});
 const layers=CLIMATE_LAYERS.map(l=>[l.id,l.label]);
 function allCities(){if(layer==='grandine')return hailMap.points();const {place,weather}=ctx.get(),list=cities.map(c=>({...c}));const current=list.find(c=>Math.abs(c.latitude-place.latitude)<.03&&Math.abs(c.longitude-place.longitude)<.03);if(current){current.selected=true;if(weather)current.current=weather.current}else list.unshift({...place,id:'selected',selected:true,current:weather?.current});if(timeOffset&&timeData){const at=timeData.origin+timeOffset*3600000;for(const c of list){const h=timeData.cities.find(p=>p.id===c.id)?.hours.find(h=>h.at===at);c.current=h?{...h}:null}}return list.map(c=>({...c,reportCount:cityReports(posts,c.name,layer).length}))}
 function contextButton(question,label='Chiedi all’IA'){return `<button class="ai-context" data-atlas-ai="${esc(question)}">✦ ${label}</button>`}

 function timeline(){if(['radar','segnalazioni','grandine'].includes(layer))return '';if(timeLoading)return '<section class="atmo-timeline" role="status">Caricamento delle previsioni nel tempo…</section>';if(!timeData)return '<section class="atmo-timeline"><div class="atmo-timeline-top"><div><b>Il meteo delle città, nel tempo</b><p>Esplora 24 ore prima e dopo adesso. Dati di modello, non satellite live.</p></div><button data-atmo-time-load>Apri timeline</button></div>'+(timeError?'<p role="alert">'+esc(timeError)+'</p>':'')+'</section>';const at=timeData.origin+timeOffset*3600000;return '<section class="atmo-timeline"><div class="atmo-timeline-top"><label for="atmo-time">'+(timeOffset?'Previsione del modello · <span class="atmo-time-label">'+new Date(at).toLocaleString('it-IT',{timeZone:'UTC',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' UTC</span>':'Adesso · dati del modello')+'</label><button data-atmo-time-now>Torna adesso</button></div><input id="atmo-time" type="range" min="-24" max="24" value="'+timeOffset+'" step="1" aria-label="Previsioni delle città da meno 24 a più 24 ore"><div class="atmo-timeline-scale"><span>−24 ore</span><span>Adesso</span><span>+24 ore</span></div><p>Open-Meteo · cambia i simboli e i valori delle città. Anche le ore passate sono dati di modello; non mostra il movimento reale delle nuvole.</p></section>'}
 async function loadTimeline(){if(timeLoading)return;timeLoading=true;timeError='';if($('#atmo-timeline-slot'))$('#atmo-timeline-slot').innerHTML=timeline();try{timeData=await ctx.api('atmosphere/timeline')}catch(e){timeError=e.message}finally{timeLoading=false;if($('#atmo-timeline-slot')){$('#atmo-timeline-slot').innerHTML=timeline();bindTimeline()}refresh()}}
 function bindTimeline(){$('[data-atmo-time-load]')?.addEventListener('click',loadTimeline);$('[data-atmo-time-now]')?.addEventListener('click',()=>{timeOffset=0;$('#atmo-timeline-slot').innerHTML=timeline();bindTimeline();refresh()});const range=$('#atmo-time');if(range)range.oninput=()=>{timeOffset=Number(range.value);const label=$('label[for="atmo-time"]');label.textContent=timeOffset?'Modello · '+new Date(timeData.origin+timeOffset*3600000).toLocaleString('it-IT',{timeZone:'UTC',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' UTC':'Adesso · dati del modello';refresh()}}
 function openCity(p){if(layer==='grandine'){scene?.focus(p);hailMap.open(p);return}scene?.focus(p);const w=p.current,definition=layerDefinition(layer),value=climateValue(w,layer);ctx.modal(p.name,'<p>'+(value!==null?esc(definition.label)+': '+value:w?weatherName(w.weather_code)+' · '+valueText(w.temperature_2m,'°'):'Scegli cosa vedere in questa città.')+'</p>'+(w?.time?'<p>Modello Open-Meteo · '+esc(w.time.replace('T',' '))+' · '+esc(timeOffset||!p.selected?'UTC':ctx.get().weather?.timezone||'orario della fonte')+'</p>':'')+'<p>Le testimonianze mostrano ciò che le persone raccontano. Controlla sempre data e provenienza.</p><div class="actions"><button id="atmo-dive" class="button">Entra nel cielo della città →</button><button id="atmo-city-weather">Apri previsioni</button><button id="atmo-city-select">Seleziona sul globo</button></div>',null);$('#atmo-dive').onclick=()=>{$('#dialog').close();select(p);ctx.community(true)};$('#atmo-city-weather').onclick=()=>{$('#dialog').close();select(p);location.hash='tendenze'};$('#atmo-city-select').onclick=()=>{$('#dialog').close();select(p)}}

 function miniSummary(){const {place,weather,weatherError}=ctx.get(),w=weather?.current;return `<div class="atlas-selected-copy">${miniWeather(w?.weather_code,w?.is_day!==0)}<div><h2>${esc(place.name)}</h2><p>${weatherError?'Previsioni non disponibili':w?weatherName(w.weather_code)+' · '+valueText(w.temperature_2m,'°'):'Caricamento delle previsioni…'}</p></div></div><div class="atlas-selected-actions"><a href="#tendenze" class="button">Vedi il meteo</a><button data-atlas-community>La community qui</button>${contextButton('Spiegami il meteo e cosa posso osservare nella zona di '+place.name,'Spiegami la zona')}</div>`}
 function layerInfo(){const {place}=ctx.get(),definition=layerDefinition(layer);if(definition.field)return `<b>${esc(definition.label)} · modello</b><span>Valori sulle città: ${esc(definition.unit.trim())}. ${['pioggia','rain','rovesci','neve'].includes(layer)?'Quantità nell’intervallo precedente indicato dalla fonte; nella timeline: ora precedente. ':''}Nessuna interpolazione tra le località. Tocca una città per approfondire.</span><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Fonte e unità ↗</a>`;if(layer==='radar')return `<b>Radar recente</b><span>Precipitazioni osservate. Le zone grigie indicano assenza di copertura; un’area trasparente non basta a dichiarare assenza di pioggia.</span><a href="https://www.rainviewer.com/api/color-schemes.html" target="_blank" rel="noopener">Legenda RainViewer ↗</a>`;if(layer==='grandine')return '<b>◇ Grandine segnalata</b><span>Ogni pin indica una zona dichiarata. Toccalo per vedere quando e cosa è stato segnalato. Nessun pin non significa nessun rischio.</span><a href="#grandine">Grandine chiara · fonti e Lente IA →</a>';if(layer==='segnalazioni')return '<b>Il cielo raccontato dalle persone · ultime 24 ore</b><span>Fino a 200 contributi recenti; i punti rappresentano le città indicate dagli autori. Apri la community per vedere contenuti e orari.</span><a href="#community">Apri i post</a>';return '<b>Le città e il loro meteo</b><span>Tocca un nome per aprire la località esatta. Le città vicine si separano ingrandendo; la ricerca trova anche quelle non etichettate.</span>'}
 function radarControls(){if(!radarVisible())return '';if(radarLoading)return '<p role="status">Caricamento del radar…</p>';if(radarError)return `<p role="alert">${esc(radarError)}</p><button data-radar-retry>Riprova radar</button>`;if(!radarData)return '<button data-radar-retry>Carica il radar</button>';const f=radarData.frames[radarIndex];return `<div class="radar-playback"><button data-radar-play aria-pressed="${radarPlaying}">${radarPlaying?'Pausa':'Riproduci le ultime immagini'}</button><button data-radar-latest>Immagine più recente</button></div><div class="radar-timeline"><label for="radar-time">Immagine delle <strong>${new Date(f.time*1000).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</strong> · ${new Date(f.time*1000).toLocaleDateString('it-IT')}</label><input id="radar-time" type="range" min="0" max="${radarData.frames.length-1}" value="${radarIndex}" aria-label="Scegli un’immagine radar delle ultime due ore"><div><span>Circa 2 ore fa</span><span>Più recente</span></div><small>Pioggia e neve secondo RainViewer; non rileva la grandine. Grigio: copertura non disponibile. Ora di composizione dell’immagine, non di ogni singola rilevazione. Fonte: <a href="https://www.rainviewer.com/" target="_blank" rel="noopener">RainViewer</a>.</small></div>`}
 function page(){if(!FEATURES.hailMap&&layer==='grandine')layer='meteo';if(ctx.get().route==='radar')layer='radar';if(FEATURES.hailMap&&ctx.get().route==='grandine-mappa')layer='grandine';hailMap.setVisible(layer==='grandine');return `<section class="atlas-workspace"><div class="atlas-title"><div><h1>${mode()==='globe'?'Esplora il mondo.':'La tua zona, da vicino.'}</h1><p>${mode()==='globe'?'Ruota il pianeta. Scegli una città. Scopri il suo cielo.':'Mappa, radar e osservazioni nello stesso posto.'}</p></div><a href="#guida" class="guide-link">? Guida</a></div><div class="atlas-top"><div class="atlas-view-switch"><a href="#globo-meteo" ${mode()==='globe'?'aria-current="page"':''}>Globo meteo</a><a href="#mappa" ${mode()==='map'?'aria-current="page"':''}>Mappa</a></div>${ctx.searchForm()}<button data-atlas-gps aria-label="Usa la mia posizione per il meteo">⌖ Vicino a me</button></div>${ctx.google3dEntry?.()||''}${layerControls(layer)}${mode()==='globe'?`<div class="climate-quality"><label>Qualità del globo<select id="globe-quality"><option value="high" ${quality==='high'?'selected':''}>Alta qualità</option><option value="light" ${quality==='light'?'selected':''}>Leggera</option></select></label><p>Immagine NASA fino a 5400 px · rispetta le impostazioni Comfort</p></div>`:''}<div id="atlas-live-status" class="climate-source-strip">${sourceStatus()}</div><div id="atlas-hail-controls">${hailMap.controls()}</div><section class="atlas-stage ${mode()==='map'?'map-stage':'globe-stage'}"><div id="atlas-canvas" class="atlas-canvas" role="region" aria-label="${mode()==='map'?'Mappa interattiva':'Globo con le città'}"><p>Caricamento della ${mode()==='map'?'mappa':'Terra'}…</p></div><div class="planet-breadcrumb"><button data-atlas-orbit>Terra</button><span>›</span><button data-atlas-center>${esc(ctx.get().place.name)}</button><a href="#mappa">Esplora le strade ↗</a></div>${ctx.lenteEntry?.({section:mode()==='map'?'map':'globe',layer,small:true,label:'Spiega la zona · Lente IA'})||''}<div class="atlas-stage-tools"><button data-atlas-fullscreen aria-label="Apri o chiudi vista a schermo intero">⛶</button><button data-atlas-zoom="in" aria-label="Ingrandisci">＋</button><button data-atlas-zoom="out" aria-label="Riduci">−</button><button data-atlas-center aria-label="Centra sulla località selezionata">⌖</button></div><div id="atlas-map-error" role="status"></div>${mode()==='globe'?'<div class="earth-source">NASA Blue Marble · geografia storica, non satellite live</div>':''}</section><div class="atlas-source-row"><span id="city-data-status">${cityLoaded?'Città: Open-Meteo · dati del modello':cityError?esc(cityError):'Caricamento del meteo delle città…'}</span><button data-atlas-reload>Aggiorna dati</button></div><div id="atmo-timeline-slot">${timeline()}</div><div id="atlas-radar-controls">${radarControls()}</div><div class="atlas-layer-note" id="atlas-layer-note">${layerInfo()}</div><div id="atlas-hail-list">${hailMap.list()}</div><div id="atlas-hail-watch" ${layer==='grandine'?'':'hidden'}>${hailMap.watchHTML()}</div>${['pioggia','grandine'].includes(layer)?ctx.nearby.panel(layer):''}<div data-atmo-alert>${ctx.safetyHTML?.()||''}</div><div id="atlas-climate-panel">${climatePanel(ctx.get().place,ctx.get().weather,layer)}</div><section class="atlas-selected" id="atlas-selected">${miniSummary()}</section><div class="atlas-discover"><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(ctx.get().place.latitude+','+ctx.get().place.longitude)}" target="_blank" rel="noopener">Google Maps ↗</a><a href="#ripari">Luoghi coperti vicini →</a><a href="#fitcheck">Fit Check · come ci si veste qui →</a><a href="#tendenze">Previsioni e tendenze →</a><button data-atlas-question>Chiedilo a chi è qui</button>${contextButton('Come si legge il livello '+layers.find(l=>l[0]===layer)?.[1]+' in MeteoSocial?','Spiegami questo livello')}</div></section>`}
 function weatherHero(){const {place,weather}=ctx.get(),w=weather?.current;return `<section class="weather-hero"><div class="weather-hero-copy"><span class="weather-date">${esc(place.name)} · ${w?esc(w.time.replace('T',' ')):''}</span><div class="weather-big-temp">${valueText(w?.temperature_2m,'°')}</div><h2>${weatherName(w?.weather_code)}</h2><p>Percepiti ${valueText(w?.apparent_temperature,'°')} · Min ${valueText(weather?.daily?.temperature_2m_min?.[0],'°')} · Max ${valueText(weather?.daily?.temperature_2m_max?.[0],'°')}</p><div class="weather-hero-actions">${contextButton('Riassumi il meteo di '+place.name+' in parole semplici, distinguendo previsione e allerte.','Spiegami il meteo')}<button data-atlas-question>Com’è davvero lì?</button></div></div><div class="weather-art" id="weather-art" aria-label="${weatherName(w?.weather_code)}">${miniWeather(w?.weather_code,w?.is_day!==0)}</div></section>`}
 function hourCards(){const {weather}=ctx.get(),h=weather?.hourly,start=currentHour(weather);if(start<0)return '<p>Previsione oraria non disponibile.</p>';return `<div class="forecast-hours" tabindex="0" role="region" aria-label="Previsioni orarie scorrevoli">${h.time.slice(start,start+24).map((t,k)=>{const i=k+start;return `<article><time>${t.slice(11,16)}</time>${miniWeather(h.weather_code?.[i],h.is_day?.[i]!==0)}<b>${valueText(h.temperature_2m[i],'°')}</b><span class="rain-prob">${valueText(h.precipitation_probability?.[i],'%')}</span><small>${valueText(h.wind_speed_10m?.[i],' km/h')}</small></article>`}).join('')}</div><p class="forecast-footnote">Percentuali: probabilità di pioggia. Orari della località scelta.</p>`}
 function weatherContent(){const {weather}=ctx.get(),w=weather?.current,d=weather?.daily;if(!weather)return '';if(weatherTab==='ore')return `<section class="forecast-section"><h2>Le prossime 24 ore</h2>${hourCards()}${contextButton('In quali ore aumenta la probabilità di pioggia nelle prossime 24 ore?')}</section>`;
 if(weatherTab==='settimana'){const t=trendSummary(weather);return `<section class="forecast-section"><div class="trend-pills"><div><span>Domani rispetto a oggi</span><strong>${t?.delta==null?'—':(t.delta>0?'+':'')+valueText(t.delta,'°',1)}</strong><small>Variazione della massima prevista</small></div><div><span>Giorno con probabilità più bassa</span><strong>${t?.driest?new Date(d.time[t.driest.i]+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long'}):'—'}</strong><small>${t?.driest?valueText(t.driest.v,'% pioggia'):''}</small></div></div><h2>La settimana, a colpo d’occhio</h2><div class="forecast-week">${(d?.time||[]).map((day,i)=>`<article><b>${i===0?'Oggi':new Date(day+'T12:00:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric'})}</b>${miniWeather(d.weather_code[i])}<span>${weatherName(d.weather_code[i])}</span><strong>${valueText(d.temperature_2m_min[i],'°')} <em>${valueText(d.temperature_2m_max[i],'°')}</em></strong><small>${valueText(d.precipitation_probability_max[i],'% pioggia')}</small></article>`).join('')}</div><p class="forecast-footnote">L’incertezza aumenta andando avanti nei giorni. Le tendenze sono una lettura dei dati, non un bollettino di allerta.</p><div class="weather-tools-row">${contextButton('Qual è la tendenza dei prossimi sette giorni? Spiega anche l’incertezza.')}<button id="download-trend">Scarica la card meteo</button></div></section>`}
 if(weatherTab==='uscire'){const best=bestWindow(weather,activity);return `<section class="forecast-section"><div class="activity-choices">${[['walk','Passeggiata'],['cycle','Bici'],['outside','Tempo all’aperto']].map(([id,label])=>`<button data-activity="${id}" aria-pressed="${activity===id}">${label}</button>`).join('')}</div><div class="outing-window"><span>QUANDO CONVIENE USCIRE?</span><h2>${best?best.start.slice(11,16)+' – '+best.end.slice(11,16):'Nessuna finestra nei criteri'}</h2><p>${best?new Date(best.start.slice(0,10)+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'})+' · '+valueText(best.temp,'°')+' · pioggia fino al '+best.rain+'% · vento fino a '+best.wind+' km/h':'Nelle prossime 24 ore non ci sono dati sufficienti o condizioni entro i limiti scelti.'}</p><p class="small">Confrontiamo soltanto ore diurne e con dati completi. È un suggerimento organizzativo, non una garanzia di sicurezza.</p></div><details class="outing-criteria"><summary>Perché questo orario?</summary><p>${activity==='cycle'?'Per la bici: vento fino a 20 km/h, pioggia fino al 25%, temperatura da 8° a 29°.':activity==='outside'?'Per stare all’aperto: vento fino a 25 km/h, pioggia fino al 30%, temperatura da 12° a 30°.':'Per una passeggiata: vento fino a 25 km/h, pioggia fino al 30%, temperatura da 5° a 32°.'} Escludiamo le ore con temporali previsti; tra quelle rimanenti preferiamo meno pioggia, meno vento e temperature vicine a 21°. Controlla comunque le allerte ufficiali.</p></details><div class="weather-tools-row"><button data-atlas-question>Chiedi conferma alla zona</button>${contextButton('Aiutami a scegliere quando uscire nelle prossime 24 ore: '+({walk:'passeggiata',cycle:'bici',outside:'tempo all’aperto'}[activity])+'. Non dichiarare un luogo sicuro.')}</div></section>`}
 return `<section class="forecast-section"><div class="weather-metrics"><article><span>Vento</span><b>${valueText(w.wind_speed_10m,' km/h')}</b><small>Raffiche ${valueText(w.wind_gusts_10m,' km/h')}</small></article><article><span>Pioggia</span><b>${valueText(w.precipitation,' mm',1)}</b><small>Quantità stimata nell’intervallo</small></article><article><span>Umidità</span><b>${valueText(w.relative_humidity_2m,'%')}</b><small>Umidità relativa</small></article><article><span>Indice UV</span><b>${valueText(d?.uv_index_max?.[0],'',1)}</b><small>Massimo previsto oggi</small></article></div><div class="sun-times"><span>Alba <b>${d?.sunrise?.[0]?.slice(11,16)||'—'}</b></span><span>Tramonto <b>${d?.sunset?.[0]?.slice(11,16)||'—'}</b></span><span>Nuvole <b>${valueText(w.cloud_cover,'%')}</b></span></div><h2>Porto l’ombrello?</h2>${hourCards()}<div class="weather-tools-row"><button data-weather-tab="uscire">Trova un buon momento per uscire</button><button data-weather-tab="settimana">Guarda la tendenza</button></div></section>`}
 function weatherPage(){const {weather,weatherError,place}=ctx.get();return `<section class="weather-workspace"><div class="atlas-title"><div><h1>Il tuo meteo. Senza complicazioni.</h1><p>${esc(place.name)}</p></div><a href="#guida" class="guide-link">? Guida</a></div><div data-atmo-alert>${ctx.safetyHTML?.()||''}</div>${weather?weatherHero():`<section class="weather-empty"><h2>${weatherError?'La fonte meteo non risponde':'Caricamento delle previsioni…'}</h2><p>${weatherError?'Riprova oppure cambia città.':'Puoi aprire la community mentre attendi.'}</p><button data-refresh-weather>Riprova</button><a href="#mappa">Cambia città</a></section>`}<div class="atlas-lente-slot">${ctx.lenteEntry?.({section:'weather',label:'La giornata, spiegata bene',description:'Ombrello, orari e tendenze. Chiedi a Lente.'})||''}</div><div class="forecast-tabs" aria-label="Periodo delle previsioni">${[['oggi','Adesso'],['ore','24 ore'],['settimana','7 giorni'],['uscire','Quando uscire']].map(([id,label])=>`<button data-weather-tab="${id}" aria-pressed="${weatherTab===id}">${label}</button>`).join('')}</div><div id="weather-content">${weatherContent()}</div><div class="weather-source">Fonte: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a> · ${weather?esc(weather.timezone)+' · dato '+esc(weather.current.time.replace('T',' ')):'Dati non disponibili'} · previsioni da modello.</div><details class="weather-compare"><summary>Confronta con un’altra città</summary><label>Seconda città<select id="compare-city">${CITIES.filter(c=>c.name!==place.name).map(c=>`<option value="${c.id}" ${compare===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><div id="compare-result">${compareContent()}</div></details><div class="weather-links"><a href="#fitcheck">Come si veste la community? Apri Fit Check →</a><a href="#ripari">Quanto è vicina la pioggia? Trova copertura →</a><a href="#sfide">La sfida della tua città →</a><a href="#mappa">Vedi radar e mappa</a><button data-atlas-community>La community qui</button><a href="https://www.protezionecivile.gov.it/it/" target="_blank" rel="noopener">Bollettini ufficiali ↗</a></div></section>`}
 function compareContent(){const c=cities.find(c=>c.id===compare),w=c?.current;return w?`<p><b>${esc(c.name)} ${valueText(w.temperature_2m,'°')}</b> · ${weatherName(w.weather_code)} · vento ${valueText(w.wind_speed_10m,' km/h')}</p><small>Open-Meteo · ${esc(w.time.replace('T',' '))} UTC</small><button data-compare-open>Apri questa città</button>`:`<p>${cityError||'Caricamento dei dati della città…'}</p>`}
 function guide(){return `<section class="app-guide"><details class="creator-guide"><summary>Nuovo: Oggi, timeline, personalità e Meteo Clash</summary><p>Oggi mostra subito temperatura, prossime ore e bollettino ufficiale della località. Segui le città per ritrovarle nel tuo account. Sul globo tocca una città e premi “Entra nel cielo della città” per aprire le Stories locali.</p><p>La timeline cambia simboli, valori e illuminazione del pianeta da −24 a +24 ore. Sono serie orarie del modello, anche nel passato: non un filmato radar o una previsione del movimento delle nuvole. Radar, Grandine e Segnalazioni conservano i propri orari.</p><p>Meteo Clash confronta due città e crea una card verticale con fonti e orari. Nello Studio trovi Clip, Testo, Meteo, Stile e Firma. “Testimonianza adesso” apre una sessione di tre minuti per scattare e pubblicare una foto dalla fotocamera: la galleria non compare, ma questo non certifica l’autenticità della scena.</p><p>Lente offre le voci Essenziale, Arcade, Premuroso e Cinico. I bollettini ufficiali italiani e le condizioni che richiedono prudenza sospendono l’ironia; con allerta rossa la risposta è deterministica e rimanda alle indicazioni ufficiali. Fuori copertura o con fonte assente, lo stato rimane non verificato.</p><a href="#home">Apri Oggi →</a><a href="#clash">Prova Meteo Clash →</a></details><details class="creator-guide"><summary>Nuovo: redazione, Studio e Storm Rooms</summary><p>Dal pulsante Crea della community apri lo Studio: importa una foto o un video, scegli il layout e prepara una slide quadrata o una clip verticale. La fotocamera richiede consenso e si ferma quando lasci la pagina. Prima di pubblicare, controlla l’anteprima e i diritti sui contenuti.</p><p>La Redazione contiene i bollettini Patch Notes, la finestra Sky-Drop e i tuoi asset. L’aspetto automatico cambia con il meteo; nel feed pioggia trovi post dichiarati Pioggia delle ultime due ore. “Tutti i cieli” torna al feed completo. Le Storm Rooms chiedono una posizione singola e hanno accesso e durata limitati.</p><a href="#studio">Apri Studio →</a><a href="#redazione">La tua redazione →</a></details><div class="atlas-title"><div><h1>Ti orienti in un minuto.</h1><p>Una città, tre punti di vista: previsione, radar e persone.</p></div><a href="#mondo">Torna alla mappa</a></div><div class="guide-steps"><article><span>1</span><div><h2>Scegli dove guardare</h2><p>Cerca una città dal selettore in alto o usa la posizione. Se compaiono nomi uguali, scegli anche regione e paese. “Vicino a me” usa la posizione soltanto dopo il tuo consenso.</p><a href="#mondo">Apri la mappa →</a></div></article><article><span>2</span><div><h2>Scegli cosa vedere</h2><p><b>Meteo:</b> condizioni previste. <b>Pioggia:</b> quantità in millimetri. <b>Radar:</b> immagini recenti delle precipitazioni, con orario. <b>Grandine:</b> post delle ultime due ore. <b>Segnalazioni:</b> contributi delle ultime 24 ore.</p><p>In Pioggia e Grandine trovi le distanze disponibili e i luoghi coperti entro 5 km. Premi “Usa la mia posizione” per usare il GPS. Il radar non identifica da solo la grandine e non calcola quando arriverà.</p><a href="#mappa">Esplora i livelli →</a></div></article><article><span>3</span><div><h2>Passa dai numeri alle persone</h2><p>Apri “Quando uscire?” per confrontare gli orari. Premi “Com’è davvero lì?” per preparare una domanda alla community. Controlla sempre località, autore e data dei post. In Community puoi filtrare gli argomenti, seguire persone, nascondere post e partecipare alle sfide delle città.</p><a href="#tendenze">Apri il meteo →</a></div></article><article><span>4</span><div><h2>Chiedi una spiegazione</h2><p>Lente IA si apre accanto alla mappa, alle previsioni o al post. I suggerimenti preparano una domanda: premi Invia quando vuoi. In Community legge solo i testi pubblici del campione, non le immagini. Le fonti sono sotto la risposta. ${ctx.get().aiReady?'Il servizio IA è collegato.':'Il servizio IA non è ancora collegato; le spiegazioni dei livelli e la lettura dei dati sono già disponibili.'} Le risposte IA possono contenere errori.</p><a href="#assistente">Apri l’assistente →</a></div></article></div><details class="creator-guide"><summary>Fit Check: i consigli sulla mappa</summary><p>Apri Fit Check dalla Community, dalla mappa o dal Meteo. Trovi foto e video pubblicati nelle ultime 24 ore, entro 5 o 20 km dal centro scelto. I pin raggruppano zone approssimate e non indicano un indirizzo o un tragitto sicuro.</p><p>Per contribuire, pubblica una foto o un video, poi premi “Aggiungi alla mappa Fit Check”. Scegli un consiglio e tocca la mappa per indicare la zona. Puoi usare il GPS solo premendo “Usa la mia zona”. Controlla l’area e conferma la pubblicazione. “Rimuovi dalla mappa” cancella la zona, lasciando il post originale.</p><a href="#fitcheck">Esplora Fit Check →</a></details><section class="guide-facts"><h2>Due cose da ricordare</h2><p>Il 40% di pioggia indica una probabilità, non una quantità. Una segnalazione di una persona non è una previsione o un’allerta ufficiale.</p><p>La mappa locale usa MapLibre e OpenFreeMap / OpenStreetMap. Il radar viene da RainViewer; vento e temperatura da Open-Meteo. Le foto e le segnalazioni delle persone sono distinte dai dati del modello.</p><a href="#impostazioni">Testo, movimento e comfort</a> · <a href="#informazioni">Fonti e dettagli</a></section></section>`}
 async function loadCities(force=false){if(cityLoading||(!force&&Date.now()-cityLoaded<600000))return;cityLoading=true;try{const d=await ctx.api('atlas/cities');cities=d.cities;cityLoaded=Date.now();cityError=''}catch(e){cityError=e.message}finally{cityLoading=false;refresh();if($('#compare-result'))$('#compare-result').innerHTML=compareContent();bindCompare()}}
 async function loadPosts(force=false){if(postLoading||(!force&&Date.now()-postsLoaded<60000))return;postLoading=true;try{const d=await ctx.api('atlas/reports');posts=d.posts;reportsTruncated=d.truncated;postsLoaded=Date.now()}catch(e){ctx.toast('Segnalazioni non disponibili: '+e.message)}finally{postLoading=false;refresh()}}
 async function loadRadar(force=false){if(radarLoading)return;if(!force&&radarData&&Date.now()-radarAt<300000){updateRadar();return}radarLoading=true;radarError='';refreshRadarControls();try{const r=await fetch('https://api.rainviewer.com/public/weather-maps.json',{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Radar temporaneamente non disponibile.');const prior=radarPlaying&&radarData?radarData.frames[radarIndex]?.time:null;radarData=parseRadar(await r.json());radarIndex=prior?Math.max(0,radarData.frames.findIndex(f=>f.time===prior)):radarData.frames.length-1;radarAt=Date.now()}catch(e){radarError=e.message;radarData=null;stopRadar();scene?.clearRadar?.();if(layer==='radar')scene?.setLayer('meteo')}finally{radarLoading=false;refreshRadarControls();if(radarData)updateRadar();refresh()}}
 function image(url){if(!imageCache.has(url)){const promise=new Promise((resolve,reject)=>{const i=new Image(),timer=setTimeout(()=>{i.onload=null;i.onerror=null;imageCache.delete(url);reject(Error('Immagini radar non disponibili. Riprova.'))},15000);i.crossOrigin='anonymous';i.onload=()=>{clearTimeout(timer);resolve(i)};i.onerror=()=>{clearTimeout(timer);imageCache.delete(url);reject(Error('Immagini radar non disponibili.'))};i.src=url});imageCache.set(url,promise);while(imageCache.size>64)imageCache.delete(imageCache.keys().next().value)}return imageCache.get(url)}
 async function radarTexture(frame,coverage=false){const canvas=document.createElement('canvas');const grid=quality==='high'?4:2;canvas.width=512*grid;canvas.height=512*grid;const c=canvas.getContext('2d');await Promise.all(Array.from({length:grid},(_,x)=>x).flatMap(x=>Array.from({length:grid},(_,y)=>y).map(async y=>{const path=coverage?'/v2/coverage/0':frame.path;const i=await image(radarData.host+path+'/512/'+(grid===4?2:1)+'/'+x+'/'+y+(coverage?'/0/0_0.png':'/2/1_1.png'));c.drawImage(i,x*512,y*512,512,512)})));return canvas}
 async function updateRadar(){if(!scene||!radarVisible()||!radarData)return;const token=++sequence,frame=radarData.frames[radarIndex];if(Date.now()-radarData.frames.at(-1).time*1000>3600000){radarError='Immagini radar non aggiornate. Premi Riprova.';radarData=null;stopRadar();scene.clearRadar?.();if(layer==='radar')scene.setLayer('meteo');refreshRadarControls();refresh();return}if(sceneType==='map'){scene.setRadar(radarData,frame);return}try{const [a,b]=await Promise.all([radarTexture(frame),radarTexture(frame,true)]);if(token===sequence&&scene&&layer==='radar')scene.setRadar(a,b)}catch(e){if(token===sequence){radarError=e.message;stopRadar();scene?.clearRadar?.();if(layer==='radar')scene?.setLayer('meteo');refreshRadarControls();refresh()}}}
 function refreshRadarControls(){const el=$('#atlas-radar-controls');if(el){el.innerHTML=radarControls();bindRadar()}}
 function select(p){view={latitude:p.latitude,longitude:p.longitude,zoom:1.65};lastPlaceKey=p.latitude+','+p.longitude;ctx.choose(p)}
 function selectPoint(p){ctx.modal('Punto sulla mappa',`<p>Coordinate ${p.latitude.toFixed(3)}°, ${p.longitude.toFixed(3)}°.</p><p>Questo punto non è stato associato a una città. Puoi consultarne il meteo oppure cercare il comune per nome.</p>`,()=>{select({...p,name:'Zona '+p.latitude.toFixed(2)+'°, '+p.longitude.toFixed(2)+'°'});return true});$('#confirm-dialog').textContent='Meteo di questo punto'}
 function bindRadar(){const play=$('[data-radar-play]');if(play)play.onclick=()=>{if(radarPlaying){stopRadar();refreshRadarControls()}else{radarPlaying=true;radarIndex=0;playRadar()}};const latest=$('[data-radar-latest]');if(latest)latest.onclick=()=>{stopRadar();if(radarData)radarIndex=radarData.frames.length-1;refreshRadarControls();updateRadar()};const range=$('#radar-time');if(range)range.oninput=()=>{stopRadar();radarIndex=Number(range.value);const label=range.previousElementSibling;label.innerHTML='Immagine delle <strong>'+new Date(radarData.frames[radarIndex].time*1000).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})+'</strong>';};if(range)range.onchange=()=>{refreshRadarControls();updateRadar();const status=$('#atlas-live-status');if(status)status.textContent=sourceStatus()};document.querySelectorAll('[data-radar-retry]').forEach(b=>b.onclick=()=>loadRadar(true))}
 function bindCompare(){const el=$('#compare-city');if(el)el.onchange=()=>{compare=el.value;$('#compare-result').innerHTML=compareContent();bindCompare()};const b=$('[data-compare-open]');if(b)b.onclick=()=>{const c=cities.find(c=>c.id===compare);if(c)select(c)}}
 function bindActions(){bindTimeline();document.querySelectorAll('[data-atlas-ai]').forEach(b=>b.onclick=()=>ctx.askAI(b.dataset.atlasAi));document.querySelectorAll('[data-atlas-community]').forEach(b=>b.onclick=()=>ctx.community());document.querySelectorAll('[data-atlas-question]').forEach(b=>b.onclick=()=>ctx.askCommunity());document.querySelectorAll('[data-weather-tab]').forEach(b=>b.onclick=()=>{weatherTab=b.dataset.weatherTab;ctx.render()});document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=b.dataset.activity;ctx.render()});bindCompare()}
 async function bind(){bindActions();if(ctx.get().route==='tendenze'){loadCities();const host=$('#weather-art'),w=ctx.get().weather?.current;if(host&&w){const token=++sequence;try{const {mountWeatherArt}=await import('./weather-art.js');if(token===sequence&&host.isConnected)art=mountWeatherArt(host,w.weather_code,w.is_day!==0)}catch{}}return}if(!isAtlas())return;hailMap.setVisible(layer==='grandine');hailMap.bind();ctx.bindReports();const host=$('#atlas-canvas');if(!host)return;const pk=ctx.get().place.latitude+','+ctx.get().place.longitude;if(pk!==lastPlaceKey){view=null;lastPlaceKey=pk}const token=++sequence,opts={center:ctx.get().place,cities:allCities(),onCity:openCity,onPoint:selectPoint,view,onView:v=>view=v,lightweight:quality==='light'||document.documentElement.classList.contains('eco-mode')||document.documentElement.classList.contains('light-rendering'),onError:text=>{if($('#atlas-map-error'))$('#atlas-map-error').textContent=text}};
 try{sceneType=mode();if(sceneType==='globe'){const {mountPlanet}=await import('./planet.js');if(token!==sequence||!host.isConnected)return;scene=mountPlanet(host,opts)}else{const {mountAtlasMap}=await import('./atlas-map.js');if(token!==sequence||!host.isConnected)return;scene=mountAtlasMap(host,opts)}scene.setLayer(layer);scene.setTime?.(timeData&&timeOffset?timeData.origin+timeOffset*3600000:Date.now())}catch(e){host.innerHTML='<div class="atlas-fallback"><h2>Questa vista non è disponibile.</h2><p>Puoi cercare la città e aprire le previsioni.</p><a href="#tendenze" class="button">Apri il meteo</a><a href="#mappa">Prova la mappa</a></div>'}
 bindLayers();const qualitySelect=$('#globe-quality');if(qualitySelect)qualitySelect.onchange=()=>{quality=qualitySelect.value==='light'?'light':'high';try{localStorage.setItem('ms-globe-quality',quality)}catch{}ctx.render()};$('[data-atlas-fullscreen]')?.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.atlas-stage').requestFullscreen()}catch{ctx.toast('Schermo intero non disponibile in questo browser.')}});document.querySelectorAll('[data-atlas-zoom]').forEach(b=>b.onclick=()=>scene?.zoom(b.dataset.atlasZoom==='in'?1.2:1/1.2));document.querySelectorAll('[data-atlas-center]').forEach(b=>b.onclick=()=>scene?.focus(ctx.get().place));$('[data-atlas-orbit]')?.addEventListener('click',()=>scene?.orbit?.());$('[data-atlas-reload]')?.addEventListener('click',()=>{loadCities(true);ctx.reloadWeather();if(radarVisible())loadRadar(true);if(layer==='segnalazioni')loadPosts(true);if(layer==='grandine')hailMap.invalidate()});$('[data-atlas-gps]')?.addEventListener('click',()=>ctx.nearby.gps());loadCities();if(radarVisible())loadRadar();if(layer==='segnalazioni')loadPosts();bindRadar();}

 function sourceStatus(){if(layer==='radar'){if(radarError)return 'Radar non disponibile: '+radarError;const frame=radarData?.frames[radarIndex];return frame?'Radar osservato · composizione '+new Date(frame.time*1000).toLocaleString('it-IT')+' (ora dispositivo). Immagini recenti con ritardo variabile, dove c’è copertura.':'Radar in attesa della fonte. Nessuna immagine non significa assenza di precipitazioni.'}if(layer==='grandine')return 'Community · controllo ogni 30 secondi con app visibile. Orario dei singoli post sui pin.';if(layer==='segnalazioni')return 'Community · racconti delle ultime 24 ore. Aggiornamento ogni 2 minuti con vista aperta.';return 'Previsioni Open-Meteo · dati sulle città. Orario della fonte nella scheda; ricontrollo periodico. Nuvole e precipitazioni del modello non sono immagini satellitari live.'}
 function bindLayers(){document.querySelectorAll('[data-atlas-layer]').forEach(b=>b.onclick=()=>changeLayer(b.dataset.atlasLayer));const picker=$('#atlas-layer-select');if(picker)picker.onchange=()=>changeLayer(picker.value)}
 function changeLayer(id){if(id==='grandine'&&!FEATURES.hailMap)return;if(!CLIMATE_LAYERS.some(l=>l.id===id))return;stopRadar();layer=id;hailMap.setVisible(layer==='grandine');$('#atlas-hail-controls').innerHTML=hailMap.controls();$('#atlas-hail-list').innerHTML=hailMap.list();if($('#atlas-hail-watch')){$('#atlas-hail-watch').hidden=layer!=='grandine';$('#atlas-hail-watch').innerHTML=hailMap.watchHTML()}hailMap.bind();ctx.bindReports();if((ctx.get().route==='grandine-mappa'&&layer!=='grandine')||(ctx.get().route==='radar'&&layer!=='radar'))location.hash='mappa';if(['radar','segnalazioni','grandine'].includes(layer)){timeOffset=0;scene?.setTime?.(Date.now())}if($('#atmo-timeline-slot'))$('#atmo-timeline-slot').innerHTML=timeline();bindTimeline();const oldPanel=$('#nearby-panel');if(oldPanel)oldPanel.remove();if(['pioggia','grandine'].includes(layer)){$('#atlas-selected').insertAdjacentHTML('beforebegin',ctx.nearby.panel(layer));ctx.nearby.bind()}sequence++;if($('#atlas-map-error'))$('#atlas-map-error').textContent='';scene?.setLayer(layer);document.querySelectorAll('[data-atlas-layer]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.atlasLayer===layer)));$('#atlas-layer-note').innerHTML=layerInfo();refreshRadarControls();refresh();if(radarVisible())loadRadar();if(layer==='segnalazioni')loadPosts();const picker=$('#atlas-layer-select');if(picker)picker.value=layer;}
 function stopRadar(){radarPlaying=false;radarGeneration++;clearTimeout(radarTimer);radarTimer=0}
 async function playRadar(){if(!radarPlaying||!isAtlas()||!radarVisible()||document.hidden||!radarData){stopRadar();refreshRadarControls();return}const generation=radarGeneration;await updateRadar();if(generation!==radarGeneration)return;refreshRadarControls();const status=$('#atlas-live-status');if(status)status.textContent=sourceStatus();if(radarPlaying)radarTimer=setTimeout(()=>{if(radarData)radarIndex=(radarIndex+1)%radarData.frames.length;playRadar()},2000)}
 function refreshSources(){if(document.hidden||!isAtlas())return;loadCities();if(radarVisible())loadRadar(true);if(layer==='segnalazioni')loadPosts(true);if(timeData&&Date.now()-timeData.updated>600000)loadTimeline();if(!ctx.get().weather||Date.now()-ctx.get().weather._loadedAt>600000)ctx.reloadWeather()}
 setInterval(refreshSources,120000);
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopRadar();refreshRadarControls()}else refreshSources()});

 function refresh(){hailMap.paint();const panel=$('#atlas-climate-panel');if(panel)panel.innerHTML=climatePanel(ctx.get().place,ctx.get().weather,layer);const status=$('#atlas-live-status');if(status)status.textContent=sourceStatus();bindLayers();scene?.setTime?.(timeData&&timeOffset?timeData.origin+timeOffset*3600000:Date.now());const lens=$('.atlas-stage [data-lente-entry]');if(lens)lens.dataset.lenteLayer=layer;const explain=$('.atlas-discover [data-atlas-ai]');if(explain)explain.dataset.atlasAi='Come si legge il livello '+layers.find(l=>l[0]===layer)?.[1]+' in MeteoSocial?';if(scene&&isAtlas())scene.setCities(allCities());if($('#atlas-selected'))$('#atlas-selected').innerHTML=miniSummary();if($('#city-data-status'))$('#city-data-status').textContent=cityError||(!cityLoaded?'Caricamento del meteo delle città…':'Città: Open-Meteo · previsioni aggiornate; orario nella scheda');if($('#atlas-layer-note'))$('#atlas-layer-note').innerHTML=layerInfo();bindActions()}
 return {page,weatherPage,guide,bind,refresh,invalidateReports:()=>hailMap.invalidate(),aiContext:()=>({section:ctx.get().route==='tendenze'?'weather':mode()==='map'?'map':'globe',layer}),dispose(){stopRadar();hailMap.setVisible(false);sequence++;if(sceneType==='globe'&&scene)view=scene.view();scene?.dispose();scene=null;art?.();art=null;events?.abort()}};
}
